JSON.stringify({\n      type: 'draft',\n      source: 'workbench',\n      prompt,\n    }),\n  );\n}\n</script>\n\n<style scoped>\n.panel-title {\n  min-height: 32px;\n  padding: 2px 4px 6px !important;\n  border-bottom: 0;\n}\n.panel-label {\n  display: inline-flex;\n  align-items: center;\n  gap: 7px;\n  color: var(--pm-text-subtle);\n  font-size: 12px;\n  font-weight: 640;\n  line-height: 1;\n}\n.add-btn {\n  width: 28px;\n  height: 28px;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  border-radius: 999px;\n  border: 1px solid transparent;\n  background: transparent;\n  color: var(--pm-text-muted);\n  cursor: pointer;\n  transition: all 0.12s;\n}\n.add-btn:hover {\n  background: var(--pm-bg-hover);\n  color: var(--pm-text);\n  border-color: var(--pm-border);\n}\n.draft-list {\n  padding: 0 1px 8px;\n}\n.empty-hint {\n  padding: 14px 8px;\n  color: var(--pm-text-subtle);\n  font-size: 12px;\n  text-align: center;\n}\n.draft-item {\n  border: 1px solid transparent;\n  border-bottom-color: transparent;\n  border-radius: 0;\n  background: transparent;\n  cursor: grab;\n  transition: background 0.12s, border-color 0.12s;\n}\n.draft-item:hover {\n  border-color: transparent;\n  background: var(--pm-bg-hover);\n}\n.draft-header {\n  display: flex;\n  align-items: center;\n  min-height: 40px;\n  padding: 7px 9px;\n  cursor: pointer;\n}\n.draft-name {\n  font-size: 13px;\n  color: var(--pm-text);\n  font-weight: 520;\n}\n.del-btn {\n  width: 20px;\n  height: 20px;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  border-radius: 4px;\n  border: none;\n  background: transparent;\n  color: var(--pm-text-subtle);\n  cursor: pointer;\n}\n.del-btn:hover {\n  color: var(--pm-danger);\n  background: color-mix(in srgb, var(--pm-danger) 13%, transparent);\n}\n.draft-body {\n  padding: 7px 8px 10px;\n  display: flex;\n  flex-direction: column;\n  gap: 6px;\n  border-top: 1px solid var(--pm-divider);\n  background: color-mix(in srgb, var(--pm-bg-hover) 42%, transparent);\n}\n.draft-input,\n.draft-select {\n  width: 100%;\n  padding: 6px 9px;\n  border-radius: 8px;\n  border: 1px solid var(--pm-border);\n  background: var(--pm-input-bg);\n  color: var(--pm-text);\n  font-size: 12px;\n  outline: none;\n}\n.draft-input:focus,\n.draft-select:focus {\n  border-color: var(--pm-border-strong);\n}\n.draft-select option {\n  background: var(--pm-bg-elevated);\n}\n.draft-textarea {\n  width: 100%;\n  padding: 8px 9px;\n  border-radius: 8px;\n  border: 1px solid var(--pm-border);\n  background: var(--pm-input-bg);\n  color: var(--pm-text);\n  font-size: 12px;\n  resize: vertical;\n  min-height: 60px;\n  outline: none;\n  font-family: inherit;\n}\n.draft-textarea:focus {\n  border-color: var(--pm-border-strong);\n}\n</style>\n"],"sourceRoot":""}]);
