</button>\n        <button class=\"folder-btn\" title=\"删除文件夹\" @click=\"$emit('delete')\">\n          <i class=\"fas fa-trash text-xs\" />\n        </button>\n      </div>\n    </div>\n\n    <div\n      v-if=\"!folder.collapsed\"\n      class=\"folder-items\"\n      @dragover.prevent=\"onDragOver\"\n      @dragleave=\"isDragOver = false\"\n      @drop.prevent=\"onDrop\"\n      :class=\"{ 'drag-over': isDragOver }\"\n    >\n      <div v-if=\"!folder.items.length\" class=\"empty-folder text-slate-600 text-xs text-center py-2\">\n        拖拽条目到此处\n      </div>\n      <div\n        v-for=\"(item, i) in folder.items\"\n        :key=\"`${folder.id}-${i}`\"\n        class=\"fav-item\"\n        :draggable=\"true\"\n        @dragstart=\"onItemDragStart($event, item, i)\"\n      >\n        <span class=\"fav-item-name\">{{ item.name }}</span>\n        <button class=\"fav-remove-btn\" title=\"移除\" @click=\"store.removeFromFavorites(folder.id, i)\">\n          <i class=\"fas fa-times text-xs\" />\n        </button>\n      </div>\n    </div>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { useManagerStore, type FavoriteFolder } from '../stores/manager';\n\nconst props = defineProps<{\n  folder: FavoriteFolder;\n}>();\n\nconst emit = defineEmits<{\n  delete: [];\n}>();\n\nconst store = useManagerStore();\nconst isEditing = ref(false);\nconst editName = ref('');\nconst nameInput = ref<HTMLInputElement>();\nconst isDragOver = ref(false);\n\nfunction startEdit() {\n  editName.value = props.folder.name;\n  isEditing.value = true;\n  nextTick(() => nameInput.value?.focus());\n}\n\nfunction finishEdit() {\n  if (isEditing.value && editName.value.trim()) {\n    store.renameFavoriteFolder(props.folder.id, editName.value.trim());\n  }\n  isEditing.value = false;\n}\n\nfunction cancelEdit() {\n  isEditing.value = false;\n}\n\nfunction onDragOver(e: DragEvent) {\n  e.dataTransfer!.dropEffect = 'copy';\n  isDragOver.value = true;\n}\n\nfunction onDrop(e: DragEvent) {\n  isDragOver.value = false;\n  const raw = e.dataTransfer?.getData('application/json');\n  if (!raw) return;\n\n  try {\n    const data = JSON.parse(raw);\n    const prompt = data.prompt as PresetPrompt;\n    if (!prompt || isPresetPlaceholderPrompt(prompt)) return;\n\n    store.addToFavorites(props.folder.id, {\n      id: prompt.id,\n      name: prompt.name,\n      enabled: prompt.enabled ?? true,\n      position: (prompt as any).position ?? { type: 'relative' as const },\n      role: prompt.role,\n      content: (prompt as any).content ?? '',\n    });\n\n    toastr.success(`已收藏 \"${prompt.name}\"`, '', { timeOut: 1500 });\n  } catch (err) {\n    console.error('[FavoriteFolder] Drop error:', err);\n  }\n}\n\nfunction onItemDragStart(e: DragEvent, item: PresetNormalPrompt, index: number) {\n  e.dataTransfer!.effectAllowed = 'copy';\n  e.dataTransfer!.setData(\n    'application/json',\n    JSON.stringify({\n      type: 'favorite',\n      source: props.folder.id,\n      index,\n      prompt: item,\n    }),\n  );\n}\n</script>\n\n<style scoped>\n.favorite-folder {\n  border: 1px solid transparent;\n  border-bottom-color: transparent;\n  border-radius: 0;\n  background: transparent;\n  overflow: hidden;\n}\n.folder-header {\n  display: flex;\n  align-items: center;\n  min-height: 40px;\n  padding: 7px 9px;\n  cursor: pointer;\n  gap: 4px;\n  transition: background 0.12s;\n}\n.folder-header:hover {\n  background: var(--pm-bg-hover);\n}\n.folder-name {\n  font-size: 13px;\n  color: var(--pm-text);\n  font-weight: 520;\n}\n.folder-name-input {\n  flex: 1;\n  padding: 4px 7px;\n  border-radius: 7px;\n  border: 1px solid var(--pm-border-strong);\n  background: var(--pm-input-bg);\n  color: var(--pm-text);\n  font-size: 12px;\n  outline: none;\n}\n.folder-actions {\n  display: flex;\n  gap: 2px;\n  opacity: 0;\n  transition: opacity 0.12s;\n}\n.folder-header:hover .folder-actions {\n  opacity: 1;\n}\n.folder-btn {\n  width: 20px;\n  height: 20px;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  border-radius: 4px;\n  border: none;\n  background: transparent;\n  color: var(--pm-text-subtle);\n  cursor: pointer;\n  transition: all 0.12s;\n}\n.folder-btn:hover {\n  color: var(--pm-text);\n  background: var(--pm-bg-hover);\n}\n.folder-items {\n  padding: 0 6px 8px 24px;\n  display: flex;\n  flex-direction: column;\n  gap: 2px;\n  transition: background 0.15s;\n  min-height: 24px;\n}\n.folder-items.drag-over {\n  background: color-mix(in srgb, var(--pm-accent) 6%, transparent);\n}\n.fav-item {\n  display: flex;\n  align-items: center;\n  min-height: 32px;\n  padding: 5px 8px;\n  border-radius: 7px;\n  background: transparent;\n  border: 1px solid transparent;\n  cursor: grab;\n  gap: 4px;\n  transition: background 0.12s, border-color 0.12s;\n}\n.fav-item:hover {\n  border-color: transparent;\n  background: var(--pm-bg-hover);\n}\n.fav-item-name {\n  flex: 1;\n  font-size: 12px;\n  color: var(--pm-text);\n  word-break: break-all;\n}\n.fav-remove-btn {\n  width: 18px;\n  height: 18px;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  border-radius: 3px;\n  border: none;\n  background: transparent;\n  color: var(--pm-text-subtle);\n  cursor: pointer;\n  flex-shrink: 0;\n  opacity: 0;\n  transition: all 0.12s;\n}\n.fav-item:hover .fav-remove-btn {\n  opacity: 1;\n}\n.fav-remove-btn:hover {\n  color: var(--pm-danger);\n  background: color-mix(in srgb, var(--pm-danger) 12%, transparent);\n}\n</style>\n"],"sourceRoot":""}]);
